using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Globalization;using System.Web.Script.Serialization;
public class TokenDay {public string Day;public long Input,Cached,Output,Reasoning,Total;}
public class TokenSnapshot {public long Input,Cached,Output,Reasoning,Total;}
public class TokenArchiveData {public Dictionary<string,string> FileSessions=new Dictionary<string,string>();public Dictionary<string,long> Cursors=new Dictionary<string,long>();public Dictionary<string,TokenSnapshot> Sessions=new Dictionary<string,TokenSnapshot>();public List<TokenDay> Days=new List<TokenDay>();}
public sealed class CodexUsageArchive {
 readonly object gate=new object();readonly string path;readonly JavaScriptSerializer json=new JavaScriptSerializer{MaxJsonLength=16777216};TokenArchiveData data=new TokenArchiveData();bool blocked;int scanning;public string Status="等待读取本地token用量事件";public int Revision;
 public CodexUsageArchive(string folder){path=Path.Combine(folder,"codex-usage-history.json");try{if(File.Exists(path)){if(new FileInfo(path).Length>16777216)throw new IOException();data=json.Deserialize<TokenArchiveData>(File.ReadAllText(path));if(data==null||data.Cursors==null||data.FileSessions==null||data.Sessions==null||data.Days==null)throw new ArgumentException();}}catch(Exception e){if(!(e is IOException)&&!(e is ArgumentException)&&!(e is InvalidOperationException)&&!(e is UnauthorizedAccessException))throw;data=new TokenArchiveData();blocked=true;Status="用量档案读取失败，原文件已保留";}}
 static long Number(Dictionary<string,object> o,string key){object v;long n;return o.TryGetValue(key,out v)&&Int64.TryParse(Convert.ToString(v,CultureInfo.InvariantCulture),out n)&&n>=0?n:0;}
 public bool Consume(string line,string session){if(line.IndexOf("\"token_count\"",StringComparison.Ordinal)<0)return false;try{var root=json.Deserialize<Dictionary<string,object>>(line);object value;if(root==null||!root.TryGetValue("type",out value)||Convert.ToString(value)!="event_msg")return false;var payload=root["payload"] as Dictionary<string,object>;if(payload==null||!payload.TryGetValue("type",out value)||Convert.ToString(value)!="token_count"||!payload.TryGetValue("info",out value))return false;var info=value as Dictionary<string,object>;if(info==null||!info.TryGetValue("total_token_usage",out value))return false;var total=value as Dictionary<string,object>;if(total==null)return false;DateTime utc;if(!root.TryGetValue("timestamp",out value)||!DateTime.TryParse(Convert.ToString(value),CultureInfo.InvariantCulture,DateTimeStyles.RoundtripKind,out utc))return false;long input=Number(total,"input_tokens"),cached=Number(total,"cached_input_tokens"),output=Number(total,"output_tokens"),reasoning=Number(total,"reasoning_output_tokens"),sum=Number(total,"total_tokens");if(input>1000000000000L||output>1000000000000L||cached>input||reasoning>output||sum!=input+output)return false;lock(gate){TokenSnapshot old;if(!data.Sessions.TryGetValue(session,out old))old=new TokenSnapshot();if(sum<=old.Total||input<old.Input||output<old.Output||cached<old.Cached||reasoning<old.Reasoning)return false;string day=utc.ToLocalTime().ToString("yyyy-MM-dd");var d=data.Days.FirstOrDefault(x=>x.Day==day);if(d==null){d=new TokenDay{Day=day};data.Days.Add(d);}d.Input+=input-old.Input;d.Cached+=cached-old.Cached;d.Output+=output-old.Output;d.Reasoning+=reasoning-old.Reasoning;d.Total+=sum-old.Total;data.Sessions[session]=new TokenSnapshot{Input=input,Cached=cached,Output=output,Reasoning=reasoning,Total=sum};Revision++;return true;}}catch(ArgumentException){}catch(InvalidOperationException){}catch(KeyNotFoundException){}return false;}
 static IEnumerable<string> Files(string root){var todo=new Stack<string>();todo.Push(root);int directories=0;while(todo.Count>0&&directories++<3000){string dir=todo.Pop();if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)continue;foreach(string p in Directory.GetFiles(dir,"rollout-*.jsonl"))if((File.GetAttributes(p)&FileAttributes.ReparsePoint)==0)yield return p;foreach(string d in Directory.GetDirectories(dir))todo.Push(d);}}
 public void Scan(string home){if(System.Threading.Interlocked.Exchange(ref scanning,1)!=0)return;try{ScanCore(home);}finally{System.Threading.Interlocked.Exchange(ref scanning,0);}}
 void ScanCore(string codexHome){if(String.IsNullOrWhiteSpace(codexHome))codexHome=Environment.GetEnvironmentVariable("CODEX_HOME");if(String.IsNullOrWhiteSpace(codexHome))codexHome=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),".codex");if(!Path.IsPathRooted(codexHome)||codexHome.StartsWith(@"\\")){Status="请选择本地Codex数据目录";return;}string sessions=Path.Combine(codexHome,"sessions");if(!Directory.Exists(sessions)){Status="未找到本地sessions目录，请选择Codex数据目录";return;}try{long budget=8*1024*1024;int scanned=0;var files=Files(sessions).OrderByDescending(File.GetLastWriteTimeUtc).Take(10000).ToArray();foreach(string file in files){if(budget<=0||scanned>=16)break;var fi=new FileInfo(file);string id=Path.GetFileNameWithoutExtension(file);if(id.Length>=36)id=id.Substring(id.Length-36);long offset;lock(gate){data.Cursors.TryGetValue(file,out offset);string known;if(data.FileSessions.TryGetValue(file,out known))id=known;}if(fi.Length<offset)offset=0;if(fi.Length==offset)continue;scanned++;using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){stream.Position=offset;while(stream.Position<stream.Length&&budget>0){long begin=stream.Position;var bytes=new List<byte>();int b;while((b=stream.ReadByte())>=0&&b!=10){if(bytes.Count<131072)bytes.Add((byte)b);budget--;}if(b<0){stream.Position=begin;break;}budget--;long next=stream.Position;if(bytes.Count<131072){string line=Encoding.UTF8.GetString(bytes.ToArray()).TrimStart('\uFEFF').TrimEnd('\r');if(line.Contains("\"session_meta\"")){try{var meta=json.Deserialize<Dictionary<string,object>>(line);object kind,payload;if(meta.TryGetValue("type",out kind)&&Convert.ToString(kind)=="session_meta"&&meta.TryGetValue("payload",out payload)){var detail=payload as Dictionary<string,object>;object identity;Guid guid;if(detail!=null&&detail.TryGetValue("id",out identity)&&Guid.TryParse(Convert.ToString(identity),out guid)){id=guid.ToString();lock(gate)data.FileSessions[file]=id;}}}catch(ArgumentException){}catch(InvalidOperationException){}}Consume(line,id);}offset=next;}}lock(gate)data.Cursors[file]=offset;}lock(gate){if(blocked)return;Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";File.WriteAllText(temp,json.Serialize(data),new UTF8Encoding(false));if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);Status="本地用量事件 · 本轮增量读取 "+scanned+" 个日志；累计 "+data.Sessions.Count+" 个会话（非官方账单）";}}catch(Exception e){if(!(e is IOException)&&!(e is UnauthorizedAccessException)&&!(e is ArgumentException)&&!(e is InvalidOperationException))throw;Status="本地用量读取暂不可用，保留已有记录";}}
 public TokenDay[] Range(DateTime start,DateTime end){lock(gate)return data.Days.Where(d=>String.CompareOrdinal(d.Day,start.ToString("yyyy-MM-dd"))>=0&&String.CompareOrdinal(d.Day,end.ToString("yyyy-MM-dd"))<0).Select(d=>new TokenDay{Day=d.Day,Input=d.Input,Cached=d.Cached,Output=d.Output,Reasoning=d.Reasoning,Total=d.Total}).ToArray();}
}
